const defaultArchiveKeywords: ArchiveKeywordConfig = {
  summary: '摘要库,摘要,summary,digest',
  report: '综合库,综合,学情,汇总,分析,report,overview,总览,周报,月报,阶段',
  qa: '咨询精华库,问答,qa,q&a,对话,咨询,精华',
};

function loadArchiveKeywords(): ArchiveKeywordConfig {
  try {
    return { ...defaultArchiveKeywords, ...JSON.parse(localStorage.getItem(archiveKeywordStorageKey) || '{}') };
  } catch {
    return defaultArchiveKeywords;
  }
}

function saveArchiveKeywords(value: ArchiveKeywordConfig) {
  localStorage.setItem(archiveKeywordStorageKey, JSON.stringify(value));
}

function keywordMatches(haystack: string, keywords: string) {
  return keywords
    .split(/[,，\n]/)
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean)
    .some((item) => haystack.includes(item));
}

function classifyMarkdownFile(file: MarkdownFile, keywordConfig: ArchiveKeywordConfig = defaultArchiveKeywords): ArchiveCategoryId {
  if (file.name.toLowerCase() === 'index.md') return 'other';
  const haystack = `${file.path}/${file.name}`.toLowerCase();
  if (keywordMatches(haystack, keywordConfig.summary)) return 'summary';
  if (keywordMatches(haystack, keywordConfig.qa)) return 'qa';
  if (keywordMatches(haystack, keywordConfig.report)) return 'report';
  if (/(实体|人物|机构|地点|entity|entities)/i.test(haystack)) return 'entity';
  if (/(概念|原理|定义|concept|concepts)/i.test(haystack)) return 'concept';
  return 'other';
}

const archiveSubjectDefinitions = [
  ['数学', /数学|math/i], ['语文', /语文|中文|作文|chinese/i], ['英语', /英语|英文|english/i],
  ['物理', /物理|physics/i], ['化学', /化学|chemistry/i], ['生物', /生物|biology/i],
  ['历史', /历史|history/i], ['地理', /地理|geography/i], ['道德与法治', /道德|法治|政治|civics/i],
  ['信息科技', /信息科技|信息技术|计算机|编程|computer|coding/i], ['科学', /科学|science/i],
] as const;

function classifyArchiveSubject(file: MarkdownFile, custom: CustomSubject[] = []) {
  const haystack = `${file.path}/${file.name}`;
  const normalized = haystack.toLocaleLowerCase('zh-CN');
  const matching = custom.find(item => item.keywords.some(word => normalized.includes(word.toLocaleLowerCase('zh-CN'))));
  if (matching) return matching.name;
  return archiveSubjectDefinitions.find(([, pattern]) => pattern.test(haystack))?.[0] || '综合/未分类';
}

function isVisibleArchiveFile(file: MarkdownFile) {
  const name = file.name.toLowerCase();
  return !['agent.md', 'soul.md', 'memory.md', 'log.md'].includes(name);
}

function isLearningReportFile(file: MarkdownFile) {
  const normalized = `${file.path}/${file.name}`.replace(/\\/g, '/').toLowerCase();
  return normalized.includes('学情报告/') || normalized.includes('/learning-report/') || normalized.includes('/learning-reports/');
}

function formatFileSize(size: number) {
  if (!Number.isFinite(size) || size <= 0) return '未知大小';
  if (size < 1024) return `${size} B`;
  if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)} KB`;
  return `${(size / 1024 / 1024).toFixed(1)} MB`;
}

function formatDateTime(value?: string) {
  if (!value) return '未知时间';
  const timestamp = Date.parse(value);
  return Number.isFinite(timestamp) ? new Date(timestamp).toLocaleString('zh-CN') : value;
}

function friendlyTaskHistoryDetail(detail?: string, executor?: string) {
  const text = String(detail || '').trim();
  if (!text) return '无补充说明';
  if (!/原工具|未确认外部任务停止|核对.*回执/.test(text)) return text;
  const provider = ({ internal: 'AI 教育管家内置流程', codex: 'Codex', workbuddy: 'WorkBuddy', qclaw: 'QClaw', manual: '人工任务包' } as Record<string, string>)[String(executor || '')]
    || String(executor || '对应执行工具');
  if (executor === 'internal') return '旧版记录：当时未完成内置任务停止确认；新版会自动核对，当前状态以任务详情为准。';
  if (executor === 'manual') return '旧版记录：当时未完成任务包状态确认；当前状态以任务详情为准。';
  return `旧版记录：当时尚未确认 ${provider} 批次停止；当前状态和具体核对步骤以任务详情为准。`;
}

