  const applyHostServiceResult = (raw?: string) => {
    if (!raw) return;
    try {
      const parsed = JSON.parse(raw);
      const status = parsed.status ?? parsed;
      if (parsed.ok === false && parsed.message) {
        setHostServiceMessage(parsed.message);
      } else {
        setHostServiceMessage(parsed.message || (status.running ? '主机服务已启动。' : '主机服务已停止。'));
      }
      setHostServiceStatus(status as HostServiceStatus);
      setHostPortDraft(String(status.port || 18777));
      refreshHostUploadRecords();
    } catch {
      setHostServiceMessage('主机服务操作失败。');
    }
  };

  const applyStorageConfig = (config: StorageConfig) => {
    activeStorageConfig = { ...defaultStorageConfig, ...config };
    setStorageConfig(activeStorageConfig);
    setDraft((current) => ({ ...current, rootPathLabel: pathsFor(current.name).root }));
    setStudents((current) => {
      const next = current.map((student) => ({
        ...student,
        rootPathLabel: student.knowledgeBaseMode === 'adopted' ? student.rootPathLabel ?? student.rootPath : pathsFor(student.name).root,
      }));
      saveStudents(next);
      syncStudentsToHost(next);
      return next;
    });
    if (config.hostServicePort) setHostPortDraft(String(config.hostServicePort));
  };

  const recordImportedFiles = (studentId: string, importedCount: number) => {
    const count = Math.max(1, Number(importedCount) || 1);
    const stamp = new Date().toLocaleString('zh-CN');
    setStudents((current) => {
      const next = current.map((student) =>
        student.id === studentId
          ? {
              ...student,
              lastImportAt: stamp,
              pendingDigestCount: (student.pendingDigestCount ?? 0) + count,
            }
          : student,
      );
      saveStudents(next);
      syncStudentsToHost(next);
      return next;
    });
  };

  const refreshInstallStatus = async (payload?: unknown) => {
    const raw = typeof payload === 'string' ? payload : await bridge()?.getAgentToolInstallStatus?.();
    if (!raw) {
      setInstallStatus(null);
      return;
    }
    try {
      const status = JSON.parse(raw) as AgentToolInstallStatus;
      setInstallStatus(status);
      if (status.probing) {
        setInstallMessage('正在后台检测本机 Agent，可继续使用其他功能。');
      } else if (!status.anyInstalled) {
        setInstallMessage('尚未检测到本机 Agent；仍可先使用教育管家和网页 Agent，安装后系统会自动接入。');
      } else {
        setInstallMessage('');
      }
      setDraft((current) => {
        if (status.probing) return current;
        const currentInstall = getAgentToolAdapter(current.agentTool).getInstall(status);
        if (getAgentToolProfile(current.agentTool).openMode === 'url' || currentInstall?.installed) return current;
        if (status.anyInstalled && !legacyAgentToolIds.has(status.recommendedTool) && status.recommendedTool !== current.agentTool) {
          return { ...current, agentTool: status.recommendedTool };
        }
        return current;
      });
    } catch {
      setInstallMessage('工具安装检测结果解析失败。');
    }
  };

  const refreshTemplateCenter = async () => {
    const raw = await bridge()?.getTemplateCenter?.(JSON.stringify(systemTemplateFiles));
    if (!raw) return;
    try {
      const result = JSON.parse(raw) as TemplateCenterState;
      setTemplateCenter(result);
      if (!result.ok) setTemplateMessage(result.message || '模板库读取失败。');
    } catch {
      setTemplateMessage('模板库读取结果解析失败。');
    }
  };

  const refreshAgentCenter = async (studentId = selectedStudent?.id) => {
    if (!studentId) return;
    const raw = await bridge()?.getAgentCenter?.(studentId);
    if (!raw) return;
    try {
      const result = JSON.parse(raw) as AgentCenterState;
      setAgentCenter(result);
      if (result.ok) {
        setUnifiedMemoryText(result.unifiedMemory || '');
        setUnifiedSoulText(result.unifiedSoul || '');
      } else {
        setAgentCenterMessage(result.message || '读取 Agent 中枢失败。');
      }
    } catch {
      setAgentCenterMessage('Agent 中枢读取结果解析失败。');
    }
  };

  const refreshAgentMemoryState = (studentId = selectedStudent?.id): Promise<void> => {
    const requestStudentId = String(studentId || '');
    if (!requestStudentId) return Promise.resolve();
    const active = agentMemoryRefreshControlRef.current.get(requestStudentId);
    if (active) {
      active.rerun = true;
      return active.promise;
    }
    const control = { promise: Promise.resolve(), rerun: false };
    control.promise = (async () => {
      do {
        control.rerun = false;
        try {
          const raw = await bridge()?.getAgentMemoryState?.(requestStudentId);
          if (!raw || selectedStudentIdRef.current !== requestStudentId) continue;
          if (agentMemoryPayloadRef.current.get(requestStudentId) === raw) continue;
          const result = JSON.parse(raw) as AgentMemorySessionState;
          agentMemoryPayloadRef.current.set(requestStudentId, raw);
          setAgentMemoryState(result);
          if (!result.ok) setAgentCenterMessage(result.message || '读取自动会话记忆失败。');
        } catch {
          if (selectedStudentIdRef.current === requestStudentId) setAgentCenterMessage('自动会话记忆读取失败，请稍后重试。');
        }
      } while (control.rerun && selectedStudentIdRef.current === requestStudentId);
    })().finally(() => {
      if (agentMemoryRefreshControlRef.current.get(requestStudentId) === control) {
        agentMemoryRefreshControlRef.current.delete(requestStudentId);
      }
    });
    agentMemoryRefreshControlRef.current.set(requestStudentId, control);
    return control.promise;
  };

  const clearEmptyAgentSessions = async (sessionId = '') => {
    if (!selectedStudent) return;
    const prompt = sessionId ? '清理这条无授权消息的已结束会话？' : '批量清理无授权消息的已结束会话？有内容及采集中的会话不会删除。';
    if (!window.confirm(prompt)) return;
    const raw = await bridge()?.deleteEmptyAgentMemorySessions?.(selectedStudent.id, sessionId);
    if (!raw) { setAgentCenterMessage('当前环境不支持清理空会话。'); return; }
    try {
      const result = JSON.parse(raw) as { ok?: boolean; message?: string };
      setAgentCenterMessage(result.message || (result.ok ? '空会话已清理。' : '清理失败。'));
      if (result.ok) refreshAgentMemoryState(selectedStudent.id);
    } catch {
      setAgentCenterMessage('清理空会话结果解析失败。');
    }
  };

  const processCapturedConversations = async (requested: AgentMemorySession[], action: 'deliver' | 'trash' | 'restore' | 'delete', selection: string, progress: (message: string) => void): Promise<string[]> => {
    const studentId = selectedStudent?.id;
    if (!studentId || selectedStudentIdRef.current !== studentId || agentMemoryState?.studentId !== studentId) return [];
    // Re-resolve the selection against the current student's latest loaded state.
    const requestedIds = new Set(requested.map(session => session.sessionId));
    const sessions = (agentMemoryState.sessions || []).filter(session => requestedIds.has(session.sessionId));
    const projectId = selection.startsWith('project:') ? selection.slice('project:'.length) : '';
    if (projectId && !conversationLinkedProjects.some((project) => project.id === projectId)) {
      progress('所选项目已不再与当前学生关联，未投递会话。');
      return [];
    }
    if (action === 'trash' && !window.confirm(`将选中的 ${sessions.length} 条自动采集会话移入回收站？已投递资料和已晋升知识不会被删除。`)) return [];
    if (action === 'delete') {
      const deletable = sessions.filter(session => canSelectCapturedSession(session) && session.materialLifecycleStatus === 'trashed' && session.materialDependencies?.canPermanentlyDelete);
      if (!deletable.length) {
        progress('所选会话存在下游依赖或尚未移入回收站，不能彻底删除。');
        return [];
      }
      if (!window.confirm(`彻底删除 ${deletable.length} 条会话的原文、本地会话记忆及未晋升知识候选？另 ${sessions.length - deletable.length} 条不符合条件，将保留。此操作不可撤销。`)) return [];
    }
    const api = bridge();
    const label = { deliver: '投递', trash: '移入回收站', restore: '恢复', delete: '彻底删除' }[action];
    const result = await runCapturedSessionBatch({ studentId, sessions, action, target: selection,
      isCurrent: () => selectedStudentIdRef.current === studentId,
      invoke: async request => action === 'deliver' ? api?.deliverConversationMaterials?.(studentId, request) : api?.manageConversationImportsAsync?.(studentId, request),
      onProgress: (done, total) => { if (selectedStudentIdRef.current === studentId) progress(`正在${label}：${done} / ${total} 条`); },
    });
    if (selectedStudentIdRef.current === studentId) {
      progress(`${label}成功 ${result.succeeded.length} 条；未完成 ${result.remaining} 条；保留不符合条件项 ${result.skipped} 条。${result.errors.slice(0, 3).join('；')}`);
      // Always reload: a failed response may have followed a successful disk write.
      await refreshAgentMemoryState(studentId);
      if (selectedStudentIdRef.current !== studentId) return result.succeeded;
      refreshConversationCenter(studentId);
      if (action === 'deliver' && result.succeeded.length) {
        if (projectId) refreshProjects(); else refreshAssets();
      }
    }
    return result.succeeded;
  };

  const manageCapturedConversation = (sessions: AgentMemorySession[], action: 'trash' | 'restore' | 'delete', progress: (message: string) => void) => processCapturedConversations(sessions, action, 'student', progress);

