  const buildConversationExtractPrompt = (student: Student) => {
    const p = pathsForStudent(student);
    const sourceMessages = conversationCenter?.latestInteraction?.messages ?? [];
    const sourceText = sourceMessages.length
      ? sourceMessages.map((message) => `[${message.id}] [${message.role}] ${message.content}`).join('\n\n')
      : '（请先点击“保存对话导入记录”，系统会生成稳定消息 ID。）';
    return `请从下面的对话历史中提取可沉淀到学生「${student.name}」教育管家的逐条知识候选。

学生信息：
- 姓名：${student.name}
- 年级：${student.grade || '待补充'}
- 学校：${student.school || '待补充'}
- 当前目标：${student.goal || '待补充'}
- 知识库根目录：${p.root}
- AGENT.md：${p.agent}
- 学情分析汇总目录：${p.summary}

每条候选必须保留逐字原文 sourceQuote 和对应 messageId；不能定位原文的内容不要输出。请只返回 JSON，不要使用 Markdown 代码块。格式：
{
  "memoryCandidates": [{"content":"长期事实或观察","sourceQuote":"原始消息中的逐字片段","messageId":"message-..."}],
  "soulSuggestions": [{"content":"人设、工作边界或偏好建议","sourceQuote":"逐字原文","messageId":"message-..."}],
  "qaHighlights": [{"content":"高价值问答结论","sourceQuote":"逐字原文","messageId":"message-..."}],
  "todos": [{"content":"后续跟进事项","sourceQuote":"逐字原文","messageId":"message-...","expiresAt":"可选 ISO 时间"}]
}

已登记的不可变对话消息如下：
${sourceText}`;
  };

  const saveConversationImport = async () => {
    if (!selectedStudent) return;
    if (!conversationText.trim()) {
      setConversationMessage('请先粘贴或输入对话历史。');
      return;
    }
    const raw = await bridge()?.saveAgentConversationImport?.(selectedStudent.id, conversationText, conversationTool);
    if (!raw) {
      setConversationMessage('当前环境不支持保存对话历史。');
      return;
    }
    try {
      const result = JSON.parse(raw) as { ok?: boolean; message?: string };
      setConversationMessage(result.message || (result.ok ? '已保存对话历史。' : '保存对话历史失败。'));
      if (result.ok) {
        refreshConversationCenter(selectedStudent.id);
        refreshSourceRegistry(selectedStudent.id);
      }
    } catch {
      setConversationMessage('保存对话历史结果解析失败。');
    }
  };

  const importConversationFromShareUrl = async () => {
    if (!selectedStudent || !conversationShareUrl.trim()) {
      setConversationShareMessage('请先粘贴对话分享链接。');
      return;
    }
    const api = bridge()?.importConversationShareUrl;
    if (!api) {
      setConversationShareMessage('当前环境不支持分享链接自动导入，请直接粘贴对话内容。');
      return;
    }
    setConversationShareBusy(true);
    setConversationShareMessage('正在读取分享链接并整理主题…');
    try {
      const result = JSON.parse(await api(selectedStudent.id, conversationShareUrl.trim(), conversationTool)) as {
        ok?: boolean;
        message?: string;
        fallbackRequired?: boolean;
      };
      const message = result.message || (result.ok ? '分享对话已导入。' : '分享链接导入失败。');
      setConversationShareMessage(message);
      setConversationMessage(message);
      if (result.ok) {
        setConversationShareUrl('');
        refreshConversationCenter(selectedStudent.id);
      }
    } catch {
      const message = '分享链接导入结果解析失败，请直接粘贴对话内容或导入文件。';
      setConversationShareMessage(message);
      setConversationMessage(message);
    } finally {
      setConversationShareBusy(false);
    }
  };

  const conversationAssetKey = (item: AgentConversationImport) => (
    `${item.sourceScopeType || 'student'}:${item.sourceScopeId || selectedStudent?.id || ''}:${item.assetId || ''}`
  );

  const toggleConversationAsset = (item: AgentConversationImport) => {
    const key = conversationAssetKey(item);
    setSelectedConversationAssetKeys((current) => current.includes(key)
      ? current.filter((value) => value !== key)
      : [...current, key]);
  };

  const manageConversationMaterials = async (action: 'trash' | 'restore' | 'delete', explicitItems?: AgentConversationImport[]) => {
    if (!selectedStudent) return;
    const selected = explicitItems ?? (conversationCenter?.index?.imports ?? []).filter((item) => (
      selectedConversationAssetKeySet.has(conversationAssetKey(item))
    ));
    if (!selected.length) {
      setConversationMessage('请先勾选要处理的对话资料。');
      return;
    }
    if (action === 'trash' && !window.confirm(`将 ${selected.length} 份对话移入回收站？已投递资料和已晋升知识不会被删除。`)) return;
    if (action === 'delete') {
      const blocked = selected.filter((item) => !item.dependencies?.canPermanentlyDelete);
      if (blocked.length) {
        const deliveryCount = blocked.reduce((sum, item) => sum + Number(item.dependencies?.deliveryCount || 0), 0);
        const promotedCount = blocked.reduce((sum, item) => sum + Number(item.dependencies?.promotedCount || 0), 0);
        setConversationMessage(`所选对话中有 ${blocked.length} 份仍关联 ${deliveryCount} 条资料投递和 ${promotedCount} 条已晋升知识，不能彻底删除；可继续保留在回收站。`);
        return;
      }
      if (!window.confirm(`彻底删除 ${selected.length} 份对话原文、本地会话记忆及未晋升知识候选？此操作不可撤销。`)) return;
    }
    const raw = await bridge()?.manageConversationImports?.(selectedStudent.id, JSON.stringify({
      action,
      confirmPermanentDelete: action === 'delete',
      sources: selected.map((item) => ({
        sourceScopeType: item.sourceScopeType || 'student',
        sourceScopeId: item.sourceScopeId || selectedStudent.id,
        assetId: item.assetId,
      })),
    }));
    if (!raw) {
      setConversationMessage('当前环境不支持对话回收站管理。');
      return;
    }
    try {
      const result = JSON.parse(raw) as { ok?: boolean; partial?: boolean; message?: string };
      setConversationMessage(result.message || (result.ok ? '对话资料已处理。' : '对话资料处理失败。'));
      if (result.ok || result.partial) {
        setSelectedConversationAssetKeys([]);
        refreshConversationCenter(selectedStudent.id);
      }
    } catch {
      setConversationMessage('对话资料治理结果解析失败。');
    }
  };

  const importConversationFiles = async () => {
    if (!selectedStudent) return;
    const raw = await bridge()?.selectAgentConversationFiles?.(selectedStudent.id, conversationTool);
    if (!raw) {
      setConversationMessage('当前环境不支持选择对话历史文件。');
      return;
    }
    try {
      const result = JSON.parse(raw) as { ok?: boolean; cancelled?: boolean; message?: string; combinedContent?: string };
      setConversationMessage(result.message || (result.ok ? '已导入对话历史文件。' : '导入对话历史文件失败。'));
      if (result.ok) {
        if (result.combinedContent) {
          setConversationText((current) => current.trim()
            ? `${current.trim()}\n\n---\n${result.combinedContent}`
            : result.combinedContent || '');
        }
        refreshConversationCenter(selectedStudent.id);
        refreshSourceRegistry(selectedStudent.id);
      }
    } catch {
      setConversationMessage('对话历史文件导入结果解析失败。');
    }
  };

  const copyConversationExtractPrompt = async () => {
    if (!selectedStudent) return;
    await copyText(buildConversationExtractPrompt(selectedStudent), '已复制对话历史提取指令。');
  };

  const buildConversationExtractPreview = (text = conversationExtractText): ConversationExtractPreview => {
    try {
      const parsed = parseLooseJson(text) as Record<string, unknown>;
      const memoryCandidates = Array.isArray(parsed.memoryCandidates)
        ? parsed.memoryCandidates
        : Array.isArray(parsed.memories)
          ? parsed.memories
          : [];
      const soulSuggestions = Array.isArray(parsed.soulSuggestions)
        ? parsed.soulSuggestions
        : Array.isArray(parsed.personaSuggestions)
          ? parsed.personaSuggestions
          : [];
      const qaHighlights = Array.isArray(parsed.qaHighlights)
        ? parsed.qaHighlights
        : Array.isArray(parsed.qa)
          ? parsed.qa
          : [];
      const todos = Array.isArray(parsed.todos)
        ? parsed.todos
        : Array.isArray(parsed.followUps)
          ? parsed.followUps
          : [];
      return { memoryCandidates, soulSuggestions, qaHighlights, todos, raw: parsed };
    } catch (error) {
      return {
        memoryCandidates: [],
        soulSuggestions: [],
        qaHighlights: [],
        todos: [],
        raw: {},
        error: error instanceof Error ? error.message : 'JSON 格式不正确',
      };
    }
  };

  const previewConversationExtractResult = () => {
    if (!conversationExtractText.trim()) {
      setConversationMessage('请先粘贴 AI 提取结果 JSON。');
      setConversationExtractPreview(null);
      return null;
    }
    const preview = buildConversationExtractPreview();
    setConversationExtractPreview(preview);
    if (preview.error) {
      setConversationMessage(`对话提取结果解析失败：${preview.error}`);
      return null;
    }
    const total = preview.memoryCandidates.length + preview.soulSuggestions.length + preview.qaHighlights.length + preview.todos.length;
    setConversationMessage(total ? `已解析提取结果：共 ${total} 条候选；保存后仍需逐条治理，不会直接写入长期知识。` : '已解析 JSON，但没有发现可登记的知识候选。');
    return preview;
  };

  const saveConversationExtractResult = async () => {
    if (!selectedStudent) return;
    const preview = conversationExtractPreview && !conversationExtractPreview.error
      ? conversationExtractPreview
      : previewConversationExtractResult();
    if (!preview || preview.error) return;
    const payload = {
      ...preview.raw,
      memoryCandidates: conversationExtractTargets.memory ? preview.memoryCandidates : [],
      soulSuggestions: conversationExtractTargets.soul ? preview.soulSuggestions : [],
      qaHighlights: conversationExtractTargets.qa ? preview.qaHighlights : [],
      todos: conversationExtractTargets.todos ? preview.todos : [],
    };
    const selectedCount = payload.memoryCandidates.length + payload.soulSuggestions.length + payload.qaHighlights.length + payload.todos.length;
    if (!selectedCount) {
      setConversationMessage('请至少选择一种要登记的知识候选。');
      return;
    }
    const raw = await bridge()?.saveConversationExtract?.(selectedStudent.id, JSON.stringify(payload, null, 2), conversationTool);
    if (!raw) {
      setConversationMessage('当前环境不支持保存对话提取结果。');
      return;
    }
    try {
      const result = JSON.parse(raw) as { ok?: boolean; message?: string };
      setConversationMessage(result.message || (result.ok ? '已保存逐条知识候选。' : '保存提取结果失败。'));
      if (result.ok) {
        setConversationExtractPreview(null);
        refreshConversationCenter(selectedStudent.id);
        refreshSourceRegistry(selectedStudent.id);
      }
    } catch {
      setConversationMessage('对话提取结果解析失败。');
    }
  };

  const toggleConversationCandidate = (candidateId: string) => {
    setSelectedConversationCandidateIds((current) => current.includes(candidateId)
      ? current.filter((id) => id !== candidateId)
      : [...current, candidateId]);
  };

  const updateConversationCandidate = async (candidate: ConversationKnowledgeCandidate, action: string, payload: Record<string, unknown> = {}) => {
    if (!selectedStudent) return;
    const raw = await bridge()?.updateConversationKnowledgeCandidate?.(selectedStudent.id, candidate.id, action, JSON.stringify(payload));
    if (!raw) {
      setConversationMessage('当前环境不支持逐条知识候选治理。');
      return;
    }
    try {
      const result = JSON.parse(raw) as { ok?: boolean; message?: string };
      setConversationMessage(result.message || (result.ok ? '候选状态已更新。' : '候选状态更新失败。'));
      if (result.ok) {
        setSelectedConversationCandidateIds((current) => current.filter((id) => id !== candidate.id));
        refreshConversationCenter(selectedStudent.id);
      }
    } catch {
      setConversationMessage('候选治理结果解析失败。');
    }
  };

  const editConversationCandidate = (candidate: ConversationKnowledgeCandidate) => {
    const content = window.prompt('编辑候选内容：', candidate.content);
    if (content === null) return;
    const sourceSnippet = window.prompt('核对原始对话中的逐字片段：', candidate.source?.snippet || '');
    if (sourceSnippet === null) return;
    const locator = window.prompt('填写消息 ID 或定位（已有消息 ID 时可保持原值）：', candidate.source?.messageId || candidate.source?.locator || '');
    if (locator === null) return;
    updateConversationCandidate(candidate, 'edit', {
      content,
      sourceSnippet,
      messageId: locator.startsWith('message-') ? locator : candidate.source?.messageId || '',
      locator: locator.startsWith('message-') ? candidate.source?.locator || '' : locator,
    });
  };

  const mergeSelectedConversationCandidates = () => {
    const selected = (conversationCenter?.governance?.candidates ?? []).filter((item) => selectedConversationCandidateSet.has(item.id));
    if (selected.length !== 2) {
      setConversationMessage('合并操作需要且只能选择两条相同类型的候选。');
      return;
    }
    if (selected[0].target !== selected[1].target) {
      setConversationMessage('只有相同知识类型的候选可以合并。');
      return;
    }
    const content = window.prompt('确认合并后的候选内容：', `${selected[0].content}\n${selected[1].content}`);
    if (content === null) return;
    updateConversationCandidate(selected[1], 'merge', { targetId: selected[0].id, content, note: '人工逐条合并' });
  };

  const promoteSelectedConversationCandidates = async () => {
    if (!selectedStudent) return;
    const selected = (conversationCenter?.governance?.candidates ?? []).filter((item) => selectedConversationCandidateSet.has(item.id));
    if (!selected.length) {
      setConversationMessage('请先选择要晋升的待审核候选。');
      return;
    }
    const blocked = selected.filter((item) => item.risk?.blocked);
    if (blocked.length) {
      setConversationMessage(`所选候选中有 ${blocked.length} 条仍被风险规则阻止，请先补充来源、处理冲突或确认敏感信息。`);
      return;
    }
    if (!window.confirm(`确认通过一个可撤销事务晋升 ${selected.length} 条候选吗？未审核内容不会一并写入。`)) return;
    const raw = await bridge()?.promoteConversationKnowledgeCandidates?.(selectedStudent.id, JSON.stringify({ candidateIds: selected.map((item) => item.id) }));
    if (!raw) {
      setConversationMessage('当前环境不支持知识候选事务晋升。');
      return;
    }
    try {
      const result = JSON.parse(raw) as { ok?: boolean; message?: string };
      setConversationMessage(result.message || (result.ok ? '候选已晋升。' : '候选晋升失败。'));
      if (result.ok) {
        setSelectedConversationCandidateIds([]);
        refreshConversationCenter(selectedStudent.id);
        refreshAgentCenter(selectedStudent.id);
      }
    } catch {
      setConversationMessage('候选晋升结果解析失败。');
    }
  };

  const rollbackConversationTransaction = async (transaction: ConversationPromotionTransaction) => {
    if (!selectedStudent || transaction.status !== 'committed') return;
    if (!window.confirm(`确认撤销事务 ${transaction.id} 吗？只移除该事务写入的标记内容，原始对话不会改变。`)) return;
    const raw = await bridge()?.rollbackConversationPromotion?.(selectedStudent.id, transaction.id);
    if (!raw) {
      setConversationMessage('当前环境不支持撤销知识晋升。');
      return;
    }
    try {
      const result = JSON.parse(raw) as { ok?: boolean; message?: string };
      setConversationMessage(result.message || (result.ok ? '事务已撤销。' : '事务撤销失败。'));
      if (result.ok) {
        refreshConversationCenter(selectedStudent.id);
        refreshAgentCenter(selectedStudent.id);
      }
    } catch {
      setConversationMessage('事务撤销结果解析失败。');
    }
  };

  const saveAgentRule = async () => {
    if (!selectedStudent) return;
    const raw = await bridge()?.saveAgentRuleFile?.(selectedStudent.id, ruleFileName, ruleContent);
    if (!raw) {
      setRuleMessage('当前环境不支持保存规则文件。');
      return;
    }
    try {
      const result = JSON.parse(raw) as AgentRulesState & { fileName?: string };
      if (result.files) setAgentRules(result);
      setRuleMessage(result.message || (result.ok ? '已保存规则文件。' : '保存规则文件失败。'));
      if (result.ok) {
        refreshAgentRules(selectedStudent.id, result.fileName || ruleFileName);
        refreshSourceRegistry(selectedStudent.id);
      }
    } catch {
      setRuleMessage('保存规则文件结果解析失败。');
    }
  };

  const previewLearningRuleMigration = () => {
    if (!selectedStudent || ruleFileName.toLowerCase() !== 'agent.md') {
      setRuleMessage('请先选择 AGENT.md，再预览纵向学习协议迁移。');
      return;
    }
    const generated = rawBuildAgentMd(selectedStudent);
    const protocol = generated.match(/## 6\.1 纵向学习分析 Protocol[\s\S]*?(?=\n## 7\. 学情报告 Protocol)/)?.[0]?.trim();
    if (!protocol) {
      setRuleMessage('当前模板缺少纵向学习协议，未修改现有规则。');
      return;
    }
    const start = '<!-- edu-manager:learning-analytics:start -->';
    const end = '<!-- edu-manager:learning-analytics:end -->';
    const block = `${start}\n${protocol}\n${end}`;
    const startAt = ruleContent.indexOf(start);
    const endAt = ruleContent.indexOf(end);
    if (startAt >= 0 && endAt > startAt) {
      setRuleContent(`${ruleContent.slice(0, startAt)}${block}${ruleContent.slice(endAt + end.length)}`);
      setRuleMessage('已在编辑区更新托管协议；请核对后点击“保存规则文件”。保存前不会写入磁盘。');
    } else if (ruleContent.includes('## 6.1 纵向学习分析 Protocol')) {
      setRuleMessage('当前 AGENT.md 已含纵向学习协议。未覆盖已有文字；如需更新请先人工比对。');
    } else {
      setRuleContent(`${ruleContent.trimEnd()}\n\n${block}\n`);
      setRuleMessage('已在编辑区追加纵向学习协议，原有规则保持不变；请核对后保存。主机会为旧文件留快照。');
    }
  };

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const [bootstrapRaw, storageRaw] = await Promise.all([
          bridge()?.getAppBootstrap?.(),
          bridge()?.getStorageConfig?.(),
        ]);
        if (cancelled) return;
        if (storageRaw) applyStorageConfig(JSON.parse(storageRaw) as StorageConfig);
        if (bootstrapRaw) {
          const result = JSON.parse(bootstrapRaw) as { ok?: boolean; students?: Student[]; license?: LicenseStatus };
          if (result.ok && Array.isArray(result.students)) {
            const nativeStudents = normalizeStudents(result.students);
            setStudents(nativeStudents);
            saveStudents(nativeStudents);
          }
          if (result.license) setLicenseStatus(result.license);
        }
      } catch {
        // The local cache keeps the shell usable while a subsystem initializes.
      }
    })();
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    if (activeSection === 'home' && selectedStudent?.id) {
      void refreshScopedAssetStatistics({ studentId: selectedStudent.id }, setHomeAssetStatistics);
    }
    if (activeSection === 'projects-existing' && selectedProject?.id) {
      void refreshScopedAssetStatistics({ projectId: selectedProject.id }, setProjectAssetStatistics);
    }
  }, [activeSection, selectedStudent?.id, selectedProject?.id]);

  useEffect(() => bridge()?.onAssetIndexChanged?.((event) => {
    if (!Number.isFinite(event.generation) || event.generation <= assetStatisticsGenerationRef.current) return;
    assetStatisticsGenerationRef.current = event.generation;
    if (activeSectionRef.current === 'assets') {
      void refreshAssets('');
      if (assetStudentFilter !== 'all') void refreshWeeklyKnowledgeGrowth(assetStudentFilter);
    }
    if (activeSectionRef.current === 'home' && selectedStudent?.id) {
      void refreshScopedAssetStatistics({ studentId: selectedStudent.id }, setHomeAssetStatistics);
    }
    if (activeSectionRef.current === 'projects-existing' && selectedProject?.id) {
      void refreshScopedAssetStatistics({ projectId: selectedProject.id }, setProjectAssetStatistics);
    }
  }), [assetStudentFilter, selectedStudent?.id, selectedProject?.id]);

  useEffect(() => {
    weeklyKnowledgeGrowthRequestRef.current += 1;
    const previousSnapshotId = weeklyKnowledgeGrowthSnapshotRef.current;
    weeklyKnowledgeGrowthSnapshotRef.current = '';
    if (previousSnapshotId) void bridge()?.invalidateWeeklyKnowledgeGrowth?.(previousSnapshotId);
    setWeeklyKnowledgeGrowth(null);
    setWeeklyKnowledgeGrowthMessage('');
    setWeeklyKnowledgeGrowthLoading(false);
    setWeeklyKnowledgeGrowthSaving(false);
    if (activeSection !== 'assets' || assetStudentFilter === 'all') return undefined;
    const timer = window.setTimeout(() => { void refreshWeeklyKnowledgeGrowth(assetStudentFilter); }, 0);
    return () => window.clearTimeout(timer);
  }, [activeSection, assetStudentFilter]);

  useEffect(() => {
    if (activeSection === 'assets') void refreshAssets(assetCursor);
    if (activeSection === 'assets') {
      void refreshDuplicateGroups(assetDuplicateCursor);
      void refreshDuplicateHistory();
      void bridge()?.getAssetRebuildStatus?.('').then((raw) => {
        const result = JSON.parse(raw) as { ok?: boolean; job?: AssetRebuildJob | null };
        if (result.ok && result.job) setAssetRebuildJob(result.job);
      }).catch(() => {});
    }
  }, [activeSection]);

  useEffect(() => {
    if (activeSection !== 'assets') return undefined;
    assetListRequestRef.current += 1;
    assetDuplicateRequestRef.current += 1;
    const timer = window.setTimeout(() => {
      setAssetCursor('');
      setAssetCursorHistory([]);
      setAssetDuplicateCursor('');
      setAssetDuplicateCursorHistory([]);
      void refreshAssets('');
      void refreshDuplicateGroups('');
    }, 300);
    return () => window.clearTimeout(timer);
  }, [activeSection, assetSearch, assetStudentFilter, assetSourceFilter, assetTypeFilter, assetDuplicateOnly]);

  useEffect(() => {
    if (!selectedAssetId || !bridge()?.getAssetDetail) {
      setSelectedAssetDetail(null);
      return undefined;
    }
    const requestId = ++assetDetailRequestRef.current;
    let cancelled = false;
    void bridge()!.getAssetDetail!(selectedAssetId).then((raw) => {
      if (cancelled || requestId !== assetDetailRequestRef.current) return;
      const result = JSON.parse(raw) as { ok?: boolean; asset?: AssetRecord };
      setSelectedAssetDetail(result.ok ? result.asset ?? null : null);
    }).catch(() => { if (!cancelled && requestId === assetDetailRequestRef.current) setSelectedAssetDetail(null); });
    return () => { cancelled = true; };
  }, [selectedAssetId, assetDetailRefreshVersion]);

  useEffect(() => bridge()?.onAssetIndexProgress?.((job) => {
    setAssetRebuildJob(job);
    setAssetBusyAction(['completed', 'failed', 'cancelled'].includes(job.status) ? '' : 'rebuild');
    const terminal = ['completed', 'failed', 'cancelled'].includes(job.status);
    const currentTime = Date.now();
    if (!terminal && activeSection === 'assets' && currentTime - assetProgressRefreshAtRef.current >= 1000) {
      assetProgressRefreshAtRef.current = currentTime;
      void refreshAssets(assetCursor);
      void refreshDuplicateGroups(assetDuplicateCursor);
    }
    if (job.status === 'completed') {
      setAssetMessage('资产索引补建完成。');
      void refreshAssets('');
      void refreshDuplicateGroups('');
    } else if (job.status === 'failed') setAssetMessage(`资产索引补建失败：${job.error || '请查看诊断信息。'}`);
    else if (job.status === 'cancelled') setAssetMessage('资产索引补建已取消，已写入的有效记录保持不变。');
  }), [activeSection, assetCursor, assetDuplicateCursor]);

  useEffect(() => bridge()?.onDuplicateCleanupProgress?.((progress) => {
    if (progress.operationId !== assetDuplicateOperation?.operationId) return;
    setAssetMessage(progress.status === 'applying'
      ? `正在安全隔离：${progress.processed ?? 0}/${progress.total ?? 0}${progress.currentPath ? ` · ${progress.currentPath}` : ''}`
      : progress.status === 'completed' ? '重复文件已移入可恢复隔离区。'
        : progress.error || `重复文件治理状态：${progress.status}`);
    if (['completed', 'partial', 'failed'].includes(progress.status)) {
      setAssetDuplicateBusy(false);
      void bridge()?.getDuplicateCleanupStatus?.(progress.operationId).then((raw) => {
        const result = JSON.parse(raw) as { ok?: boolean; operation?: AssetDuplicateOperation };
        if (result.ok && result.operation) setAssetDuplicateOperation(result.operation);
      });
      void refreshAssets('');
      void refreshDuplicateGroups('');
      void refreshDuplicateHistory();
    }
  }), [assetDuplicateOperation?.operationId]);

  useEffect(() => {
    const needsInstallStatus = activeSection === 'init'
      || (activeSection === 'settings' && (settingsSubmenu === 'connection'
        || (settingsSubmenu === 'agent-qa' && agentSettingsTab === 'tools' && agentControlSubtab === 'tool-control')));
    if (!needsInstallStatus || installStatus) return undefined;
    const timer = window.setTimeout(refreshInstallStatus, 0);
    return () => window.clearTimeout(timer);
  }, [activeSection, agentControlSubtab, agentSettingsTab, installStatus, settingsSubmenu]);

  useEffect(() => {
    if (activeSection === 'courses') void refreshCourseCatalog();
    if (activeSection === 'settings') {
      void refreshHostServiceStatus();
      void refreshLicenseStatus();
      void refreshTemplateCenter();
    }
  }, [activeSection]);

  useEffect(() => {
    const target = window as unknown as { onNativeAgentToolInstallChanged?: (payload: string) => void };
    target.onNativeAgentToolInstallChanged = refreshInstallStatus;
    return () => { delete target.onNativeAgentToolInstallChanged; };
  }, []);

  useEffect(() => {
    if (activeSection !== 'courses' && courseBrowser.open) {
      void bridge()?.closeCourseView?.();
      setCourseBrowser({ open: false });
    }
  }, [activeSection, courseBrowser.open]);

  useEffect(() => {
    if (!isWindows || courseManagementAllowed || courseSubmenu !== 'management') return;
    localStorage.setItem('edu-manager-course-submenu', 'learning');
    setCourseSubmenu('learning');
    if (activeSection === 'courses') {
      setCourseCatalogMessage('当前授权不能打开课程管理，已返回课程学习。');
    }
  }, [activeSection, courseManagementAllowed, courseSubmenu, isWindows]);

  useEffect(() => {
    (window as unknown as { onNativeImportResult?: (payload: string | NativeImportResult) => void }).onNativeImportResult = (payload: string | NativeImportResult) => {
      const result: NativeImportResult =
        typeof payload === 'string'
          ? (() => {
              try {
                return JSON.parse(payload) as NativeImportResult;
              } catch {
                return { message: payload };
              }
            })()
          : payload;
      const message = result.message || '';
      setImportMessage(message);
      if (pendingImportStudentId && (result.ok || message.startsWith('已导入'))) {
        const matchedCount = message.match(/已导入\s*(\d+)/);
        const importedCount = Number(result.imported ?? (matchedCount ? Number(matchedCount[1]) : 1));
        recordImportedFiles(pendingImportStudentId, importedCount);
      }
      window.setTimeout(() => setImportMessage(''), 3600);
    };
    (window as unknown as { onNativeUpdateResult?: (payload: string) => void }).onNativeUpdateResult = (payload: string) => {
      setCheckingUpdate(false);
      try {
        setUpdateInfo(JSON.parse(payload) as UpdateInfo);
      } catch {
        setUpdateInfo({ hasUpdate: false, message: payload || '更新检查失败' });
      }
    };
    (window as unknown as { onNativeArchiveRootSelected?: (payload: string) => void }).onNativeArchiveRootSelected = (payload: string) => {
      try {
        const result = JSON.parse(payload) as { ok?: boolean; uri?: string; message?: string };
        if (result.ok && result.uri) {
          applyStorageConfig({ ...activeStorageConfig, baseDir: result.uri, usesAbsolutePaths: true });
        }
        setArchiveRootMessage(result.ok ? '已设置学生资料根目录' : result.message || '目录授权失败');
      } catch {
        setArchiveRootMessage(payload || '目录授权失败');
      }
    };
    (window as unknown as { onNativeHostServiceChanged?: (payload: string) => void }).onNativeHostServiceChanged = (payload: string) => {
      try {
        const status = JSON.parse(payload) as HostServiceStatus;
        setHostServiceStatus(status);
        if (status.license) setLicenseStatus(status.license);
        if (activeSectionRef.current === 'settings' && settingsSubmenuRef.current === 'connection') refreshHostUploadRecords();
      } catch {
        if (activeSectionRef.current === 'settings') refreshHostServiceStatus();
      }
    };
    (window as unknown as { onNativeCourseCatalogChanged?: () => void }).onNativeCourseCatalogChanged = () => {
      refreshCourseCatalog();
    };
    (window as unknown as { onNativeCourseBrowserChanged?: (payload: { open?: boolean; courseId?: string; name?: string; blocked?: boolean; message?: string; fullscreen?: boolean; sidebarCollapsed?: boolean }) => void }).onNativeCourseBrowserChanged = (payload) => {
      setCourseBrowser({ open: Boolean(payload?.open), courseId: payload?.courseId, name: payload?.name });
      if (payload?.fullscreen === false) setCourseFullscreen(false);
      if (payload?.sidebarCollapsed === false) setSidebarCollapsed(false);
      if (payload?.blocked) setCourseCatalogMessage(payload.message || '已阻止课程页面跳转到非白名单域名。');
    };
    (window as unknown as { onNativeCollaborationChanged?: (payload: string) => void }).onNativeCollaborationChanged = (payload: string) => {
      applyCollaborationDeliveryEvent(payload);
      if (activeSectionRef.current === 'settings') {
        refreshCollaborationState();
        refreshCollaborationMaterialStats();
        refreshAgentConversationInbox();
      }
      if (activeSectionRef.current === 'projects-new' || activeSectionRef.current === 'projects-existing') refreshProjects();
      if (activeSectionRef.current === 'tasks') void refreshTaskCenter(false);
    };
    (window as unknown as { onNativeAgentMemoryChanged?: (payload: string) => void }).onNativeAgentMemoryChanged = (payload: string) => {
      try {
        const event = JSON.parse(payload) as { studentId?: string; reason?: string };
        if (String(event.studentId || '') !== selectedStudentIdRef.current) return;
        refreshAgentMemoryState(String(event.studentId));
        if (event.reason === 'codex_hook_verified') {
          setAgentCenterMessage('Codex Hook 已完成一次确认验证，后续会话将由 AI教育管家自动采集。');
        }
      } catch {
        if (selectedStudentIdRef.current) refreshAgentMemoryState(selectedStudentIdRef.current);
      }
    };

    void (async () => {
      const rootStatus = await bridge()?.getArchiveRootStatus?.();
      if (rootStatus) {
        try {
          const result = JSON.parse(rootStatus) as { ok?: boolean; uri?: string; message?: string };
          setArchiveRootMessage(result.ok ? '已授权档案目录' : result.message || '尚未授权档案目录');
        } catch {
          setArchiveRootMessage('尚未授权档案目录');
        }
      }

      const compatibilityStatus = await bridge()?.getCompatibilityStatus?.();
      if (compatibilityStatus) {
        try {
          setCompatibility(JSON.parse(compatibilityStatus) as Record<string, unknown>);
        } catch {
          setCompatibility({ ok: false, message: '兼容性检测解析失败' });
        }
      }
    })();

    let appStatusPending = false;
    let appStatusDisposed = false;
    const timer = window.setInterval(async () => {
      if (document.hidden) return;
      const visibleSection = activeSectionRef.current;
      const statusVisible = ['init', 'settings', 'memory', 'capture', 'qa', 'soul', 'rules', 'conversation', 'tasks'].includes(visibleSection);
      if (!statusVisible && visibleSection !== 'inbox') return;
      if (appStatusPending || appStatusDisposed) return;
      appStatusPending = true;
      try {
        if (statusVisible) {
          const statusApi = bridge();
          const raw = statusApi?.getAppStatusAsync ? await statusApi.getAppStatusAsync() : await statusApi?.getAppStatus?.();
          if (appStatusDisposed) return;
          if (raw) {
            try {
              const status = JSON.parse(raw) as { qclawOpened?: boolean; marvisOpened?: boolean; hohuOpened?: boolean; openclawOpened?: boolean; imaCopilotOpened?: boolean; workbuddyOpened?: boolean; codexOpened?: boolean; claudeCodeOpened?: boolean; hermesOpened?: boolean; traeOpened?: boolean; qoderWorkOpened?: boolean; obsidianOpened?: boolean };
              setQclawOpened(Boolean(status.qclawOpened));
              setMarvisOpened(Boolean(status.marvisOpened));
              setHohuOpened(Boolean(status.hohuOpened));
              setOpenclawOpened(Boolean(status.openclawOpened));
              setImaCopilotOpened(Boolean(status.imaCopilotOpened));
              setWorkbuddyOpened(Boolean(status.workbuddyOpened));
              setCodexOpened(Boolean(status.codexOpened));
              setClaudeCodeOpened(Boolean(status.claudeCodeOpened));
              setHermesOpened(Boolean(status.hermesOpened));
              setTraeOpened(Boolean(status.traeOpened));
              setQoderWorkOpened(Boolean(status.qoderWorkOpened));
              setObsidianOpened(Boolean(status.obsidianOpened));
            } catch {
              // Ignore bridge JSON parse errors.
            }
          }
        }
        const inboxRaw = visibleSection === 'inbox' ? await bridge()?.getSharedInboxStatus?.() : '';
        if (inboxRaw) {
          try {
            const inbox = JSON.parse(inboxRaw) as { count?: number };
            setSharedInboxCount(Number(inbox.count ?? 0));
          } catch {
            // Ignore inbox JSON parse errors.
          }
        }
      } catch {
        // A rejected background read must not clear the last known state.
      } finally { appStatusPending = false; }
    }, 60000);
    const hostTimer = window.setInterval(() => {
      if (!document.hidden && activeSectionRef.current === 'settings') refreshHostServiceStatus();
    }, 60000);
    return () => {
      appStatusDisposed = true;
      window.clearInterval(timer);
      window.clearInterval(hostTimer);
      delete (window as unknown as { onNativeImportResult?: (payload: string | NativeImportResult) => void }).onNativeImportResult;
      delete (window as unknown as { onNativeUpdateResult?: (payload: string) => void }).onNativeUpdateResult;
      delete (window as unknown as { onNativeArchiveRootSelected?: (payload: string) => void }).onNativeArchiveRootSelected;
      delete (window as unknown as { onNativeHostServiceChanged?: (payload: string) => void }).onNativeHostServiceChanged;
      delete (window as unknown as { onNativeCollaborationChanged?: (payload: string) => void }).onNativeCollaborationChanged;
      delete (window as unknown as { onNativeAgentMemoryChanged?: (payload: string) => void }).onNativeAgentMemoryChanged;
    };
  }, [pendingImportStudentId]);

  useEffect(() => {
    const refreshVisible = async () => {
      const section = activeSectionRef.current;
      if (section === 'inbox' && selectedId) applyDigestWorkflowPayload('student', selectedId, await bridge()?.getDigestWorkflowStatus?.('student', selectedId));
      if ((section === 'projects-new' || section === 'projects-existing') && selectedProjectId) {
        applyDigestWorkflowPayload('project', selectedProjectId, await bridge()?.getDigestWorkflowStatus?.('project', selectedProjectId));
      }
    };
    (window as unknown as { onNativeDigestWorkflowChanged?: (payload: string) => void }).onNativeDigestWorkflowChanged = (payload: string) => {
      try {
        const event = JSON.parse(payload) as { scopeType?: 'student' | 'project'; scopeId?: string };
        if (event.scopeType && event.scopeId) {
          refreshDigestWorkflow(event.scopeType, event.scopeId);
          return;
        }
      } catch {
        // Fall through to refresh the currently visible scopes.
      }
      refreshVisible();
    };
    refreshVisible();
    const timer = window.setInterval(() => {
      if (!document.hidden) refreshVisible();
    }, 30000);
    return () => {
      window.clearInterval(timer);
      delete (window as unknown as { onNativeDigestWorkflowChanged?: (payload: string) => void }).onNativeDigestWorkflowChanged;
    };
  }, [activeSection, selectedId, selectedProjectId]);

  useEffect(() => {
    if (!isWindows || !selectedId) return;
    void bridge()?.prepareAgentKnowledgeAccess?.(selectedId);
  }, [isWindows, selectedId]);

  useEffect(() => {
    const payload = hostServiceStatus?.pairPayloadText;
    if (!payload) {
      setHostPairQr('');
      return;
    }
    let cancelled = false;
    loadQrCode().then((QRCode) => QRCode.toDataURL(payload, { margin: 2, width: 320, errorCorrectionLevel: 'H' }))
      .then((url) => {
        if (!cancelled) setHostPairQr(url);
      })
      .catch(() => {
        if (!cancelled) setHostPairQr('');
      });
    return () => {
      cancelled = true;
    };
  }, [hostServiceStatus?.pairPayloadText]);

  const studentLoginQrSignature = useMemo(
    () => (hostServiceStatus?.students ?? [])
      .filter((student) => student.loginQrPayload)
      .map((student) => `${student.id}:${student.loginQrPayload}`)
      .sort()
      .join('|'),
    [hostServiceStatus?.students],
  );

  useEffect(() => {
    const loginStudents = (hostServiceStatus?.students ?? []).filter((student) => student.loginQrPayload);
    if (loginStudents.length === 0) {
      setStudentLoginQrs({});
      return;
    }
    let cancelled = false;
    Promise.all(loginStudents.map(async (student) => {
      const payload = student.loginQrPayload || '';
      let dataUrl = studentLoginQrDataUrlCache.get(payload);
      if (!dataUrl) {
        const QRCode = await loadQrCode();
        dataUrl = await QRCode.toDataURL(payload, { margin: 2, width: 220, errorCorrectionLevel: 'H' });
        studentLoginQrDataUrlCache.set(payload, dataUrl);
      }
      return [student.id, dataUrl] as const;
    }))
      .then((entries) => {
        if (!cancelled) setStudentLoginQrs(Object.fromEntries(entries));
      })
      .catch(() => {
        if (!cancelled) setStudentLoginQrs({});
      });
    return () => {
      cancelled = true;
    };
  }, [studentLoginQrSignature]);

