  const refreshAgentKnowledgeDiagnostics = async () => {
    const raw = await bridge()?.getAgentKnowledgeDiagnostics?.();
    if (!raw) return;
    try {
      const result = JSON.parse(raw) as AgentKnowledgeDiagnostics & { ok?: boolean };
      if (result.ok !== false) setAgentKnowledgeDiagnostics(result);
    } catch {
      // Diagnostics are optional and must never block ordinary questions.
    }
  };

  const askWithEducationKnowledge = async (forceRefresh = false) => {
    if (!selectedStudent || !agentKnowledgeQuestion.trim()) {
      setAgentKnowledgeResult({ ok: false, source: 'waiting', message: '请输入想了解的问题。' });
      return;
    }
    const api = bridge();
    if (!api?.queryAgentKnowledge) {
      setAgentKnowledgeResult({ ok: false, source: 'waiting', message: '当前版本不支持自动知识查询。' });
      return;
    }
    setAgentKnowledgeBusy(true);
    try {
      await api.prepareAgentKnowledgeAccess?.(selectedStudent.id);
      const teamQueryEnabled = agentKnowledgeQueryScope !== 'current_student';
      const raw = await api.queryAgentKnowledge(JSON.stringify({
        scopeType: teamQueryEnabled ? 'team' : 'student',
        scopeId: teamQueryEnabled ? 'team' : selectedStudent.id,
        queryScope: agentKnowledgeQueryScope,
        question: agentKnowledgeQuestion.trim(),
        limit: 8,
        forceRefresh,
      }));
      const result = JSON.parse(raw) as AgentKnowledgeResult;
      setAgentKnowledgeResult(result);
      refreshAgentKnowledgeDiagnostics();
      if ((result.resources?.length || result.learningContext) && result.prompt) {
        await copyText(result.prompt, result.learningContext && !(result.resources?.length)
          ? `已准备本机纵向学习证据，并打开 ${selectedStudentTool.name}；知识库查询状态请在下方核对。`
          : `已准备 ${result.resources?.length || 0} 条带来源知识，并打开 ${selectedStudentTool.name}。`);
        selectedStudentAdapter.open(openExternal);
      }
    } catch (error) {
      setAgentKnowledgeResult({
        ok: false,
        source: 'waiting',
        message: error instanceof Error ? error.message : '知识查询失败。',
      });
    } finally {
      setAgentKnowledgeBusy(false);
    }
  };

  const saveCurrentTemplates = async () => {
    const stepPrompt = (id: InitStepId) => customStepPrompts[id] ?? initSteps.find((step) => step.id === id)?.prompt ?? '';
    const templateDraft = templateKeys.reduce((acc, key) => {
      if (key === 'AGENT.md') acc[key] = templateFromGenerated(buildAgentMd(effectiveDraft), effectiveDraft);
      else if (key === 'Soul.md') acc[key] = templateFromGenerated(buildSoulMd(effectiveDraft), effectiveDraft);
      else if (key === 'Memory.md') acc[key] = templateFromGenerated(buildMemoryMd(effectiveDraft), effectiveDraft);
      else if (key === 'digest-prompt.md') acc[key] = templateFromGenerated(buildDigestCommand(effectiveDraft), effectiveDraft);
      else if (key === 'consult-prompt.md') acc[key] = activeTemplateFiles[key] || '/咨询，我想咨询';
      else acc[key] = templateFromGenerated(stepPrompt(key === 'init-step-1.md' ? 'folder' : 'agent'), effectiveDraft);
      return acc;
    }, {} as TemplateFiles);
    const raw = await bridge()?.saveCustomTemplates?.(JSON.stringify(templateDraft));
    if (!raw) {
      setTemplateMessage('当前环境不支持保存模板。');
      return;
    }
    try {
      const result = JSON.parse(raw) as TemplateCenterState;
      setTemplateMessage(result.message || (result.ok ? '已保存模板。' : '保存模板失败。'));
      refreshTemplateCenter();
    } catch {
      setTemplateMessage('保存模板结果解析失败。');
    }
  };

